import {ORES,SHAPES} from './game.js';
export {ORES,SHAPES};
export const SAVE_KEY='ember-edge-workshop-v6';
export const DAY_LENGTH=360,PACK_SIZE=4,MAX_CRATES=18,MAX_SWORDS=48,INVENTORY_SIZE=5;
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const POS={furnace:[-5,0,-5.8],valve:[-3.9,1.35,-5.1],mold:[-1.8,1.12,-5.15],anvil:[1.5,1.13,.5],hammer:[3.1,1.04,.5],tongs:[3.1,1.04,1.12],water:[6,0,.5],sale:[5.4,0,5.9],stock:[-5.8,0,3.5],orders:[-12,0,8],bed:[-6.5,0,6],scrap:[-2,0,2.8],lottery:[12,0,3],display:[-8.4,0,0]};
export const DISPLAY_SLOTS=[0,1,2].map(i=>[-8.4,1.7,-1.5+i*1.5]);
export const oreOf=id=>ORES.find(o=>o.id===id);
export const shapeOf=id=>SHAPES.find(o=>o.id===id);
// Amounts are ore-unit equivalents: homogeneous metal is poured in the same ratios as the bath.
export function materialsOf(batch){return batch?.materials??(batch?.ore?[{ore:batch.ore,amount:batch.loaded??shapeOf(batch.shape)?.cost??1}]:[]);}
function normalizeMaterials(materials){return ORES.map(o=>({ore:o.id,amount:materials.filter(m=>m.ore===o.id).reduce((n,m)=>n+m.amount,0)})).filter(m=>m.amount>0);}
export function alloyOf(batch){
 const materials=materialsOf(batch),total=materials.reduce((n,m)=>n+m.amount,0);if(!total)return null;
 const alloy={name:materials.length===1?oreOf(materials[0].ore).name:'混合金属 · '+materials.length+' 种',melt:Math.max(...materials.map(m=>oreOf(m.ore).melt))};
 for(const stat of ['sharp','hard','tough','density','cost','value'])alloy[stat]=materials.reduce((n,m)=>n+oreOf(m.ore)[stat]*m.amount/total,0);
 const rgb=[16,8,0].map(shift=>Math.round(materials.reduce((n,m)=>n+((parseInt(oreOf(m.ore).color.slice(1),16)>>shift)&255)*m.amount/total,0)));
 alloy.color='#'+rgb.map(n=>n.toString(16).padStart(2,'0')).join('');return alloy;
}
export function compositionText(batch){const materials=materialsOf(batch),total=materials.reduce((n,m)=>n+m.amount,0);return materials.map(m=>oreOf(m.ore).name+' '+Number((m.amount/total*100).toFixed(1))+'%').join(' / ');}
function primaryOre(materials){return materials.reduce((best,m)=>!best||m.amount>best.amount?m:best,null)?.ore??null;}
function portion(materials,ratio){return materials.map(m=>({ore:m.ore,amount:m.amount*ratio}));}
export const insideWorkshop=p=>Math.abs(p[0])<8.4&&p[2]>-7.4&&p[2]<7.4;
export const heldItem=s=>s.items.find(i=>i.id===s.held);
export const swordOf=(s,id)=>s.swords.find(c=>c.id===id);
export const atStation=(s,location)=>s.swords.find(c=>c.location===location);
export const carriedSword=s=>s.swords.find(c=>c.id===s.held||(s.held==='tongs'&&c.location==='tongs'));
export const carryingSword=s=>!!carriedSword(s);
export const gameTime=s=>(s.day-1)*DAY_LENGTH+s.dayTime;
export function newWorkshop(){const s={version:6,money:360,tokens:0,sold:0,income:0,best:0,broken:0,completed:0,nextId:1,day:1,dayTime:0,orders:[],held:null,inventory:Array(INVENTORY_SIZE).fill(null),selectedSlot:0,selectedShape:'longsword',player:{x:0,z:11,yaw:0,pitch:-.04},furnace:{ore:null,materials:[],additives:[],loaded:0,temp:650,progress:0,good:0,valve:false,airflow:50},mold:{fill:0,shape:null},swords:[],king:null,gameOver:null,items:[{id:'hammer',kind:'hammer',position:[...POS.hammer]},{id:'tongs',kind:'tongs',position:[...POS.tongs]},{id:'crate-starter',kind:'crate',ore:'iron',count:4,stored:true,position:[-5.8,.06,3.5]}]};s.king=makeKing(s,1);return s;}
function live(s){if(s.gameOver)throw Error('国王订单已逾期，本轮工坊经营结束。请重新开始。');}
function empty(s){live(s);if(s.held)throw Error('先右键放下手中物品。');}

function makeKing(s,level,issuedDay=s.day){const tier=Math.min(5,Math.floor((level-1)/3)),ore=ORES[tier],shape=SHAPES[(level-1)%SHAPES.length],quantity=1+Math.floor((level-1)/4);const sample={ore:ore.id,shape:shape.id,quality:18+80*.17+5*6.2,smelt:80,hits:5,stage:'finished'},stats=attributes(sample),min={quality:Math.min(55,30+level*2)};if(level>=2)min.sharp=Math.floor(stats.sharp*.78);if(level>=4)min.hard=Math.floor(stats.hard*.8);if(level>=7)min.tough=Math.floor(stats.tough*.78);return {id:'king',title:'王室军备 · 第 '+level+' 道敕令',level,ore:ore.id,shape:shape.id,min,quantity,delivered:0,tokenReward:quantity,status:'active',issuedDay,deadline:(issuedDay-1+7)*DAY_LENGTH};}
export function requirements(c){const names={quality:'品质',sharp:'锋利度',hard:'硬度',tough:'韧性',weight:'重量'};return [c.ore?'纯'+oreOf(c.ore).name:'矿种不限',c.shape?shapeOf(c.shape).name:'剑形不限',...Object.entries(c.min).map(([k,v])=>names[k]+' ≥ '+v),...(c.maxWeight?['重量 ≤ '+c.maxWeight+' kg']:[])].join(' · ');}
export function matches(c,sword){if(!c||!sword||sword.stage!=='finished')return false;const a={...attributes(sword),quality:qualityScore(sword)};return (!c.ore||materialsOf(sword).every(m=>m.ore===c.ore))&&(!c.shape||c.shape===sword.shape)&&Object.entries(c.min).every(([k,v])=>a[k]>=v)&&(!c.maxWeight||a.weight<=c.maxWeight);}
export function deadlineText(s){const left=Math.max(0,s.king.deadline-gameTime(s)),days=Math.floor(left/DAY_LENGTH),minutes=Math.ceil(left%DAY_LENGTH*2);return (days?days+' 天 ':'')+Math.floor(minutes/60)+' 时 '+(minutes%60)+' 分';}
function checkDeadline(s){if(s.gameOver||gameTime(s)<s.king.deadline)return '';if(s.king.status==='fulfilled'){const issuedDay=Math.floor(s.king.deadline/DAY_LENGTH)+1;s.king=makeKing(s,s.king.level+1,issuedDay);return '新周期开始，新的国王订单已自动下发。';}s.gameOver={day:s.day,level:s.king.level,reason:'未在期限内完成「'+s.king.title+'」'};s.furnace.valve=false;return '国王订单逾期，工坊经营失败。';}
// A finished sword contributes to at most one royal order and remains the player's property.
export function checkRoyalProgress(s){if(s.gameOver||s.king.status==='fulfilled')return '';const order=s.king;let added=0;for(const c of s.swords){if(c.creditedKing||!matches(order,c))continue;c.creditedKing=order.level;order.delivered++;added++;if(order.delivered>=order.quantity)break;}if(!added)return '';if(order.delivered===order.quantity){order.status='fulfilled';const bonus=100+order.level*80;s.money+=bonus;s.income+=bonus;s.tokens+=order.tokenReward;s.completed++;return '国王订单自动完成！赏金 '+bonus+' 金币 + '+order.tokenReward+' 枚炉印。剑保留，可出售或展示。第 '+(Math.floor(order.deadline/DAY_LENGTH)+1)+' 天发下一单。';}return '国王订单自动计入 '+added+' 把 · '+order.delivered+'/'+order.quantity+'。剑仍归你所有。';}

export const hotSword=c=>!!c&&!['finished','broken'].includes(c.stage);
export const clampedSword=s=>{const c=carriedSword(s);return c&&(c.location==='tongs'||hotSword(c))?c:null;};
function stashHands(s){for(const c of s.swords)if(['held','tongs'].includes(c.location))c.location='inventory';}
export function selectSlot(s,slot){live(s);if(!Number.isInteger(slot)||slot<0||slot>=INVENTORY_SIZE)throw Error('物品栏位置无效。');if(heldItem(s)?.kind==='crate')throw Error('先右键放下整筐矿石，再切换物品。');if(slot===s.selectedSlot)return '';const grip=atStation(s,'tongs');if(hotSword(grip))throw Error('热剑坯不能收入物品栏，请先右键放到工位或地面。');if(grip){const free=s.inventory.findIndex(id=>id===null);if(free<0)throw Error('物品栏已满，请先放下或出售夹钳中的成剑。');s.inventory[free]=grip.id;grip.location='inventory';}stashHands(s);s.selectedSlot=slot;s.held=s.inventory[slot];const c=swordOf(s,s.held);if(c)c.location='held';return '';}

export function cycleSlot(s,delta){return selectSlot(s,(s.selectedSlot+(delta>0?1:INVENTORY_SIZE-1))%INVENTORY_SIZE);}
function freeSlot(s){if(atStation(s,'tongs'))throw Error('先放下夹钳中的剑刃。');if(heldItem(s)?.kind==='crate')throw Error('先放下整筐矿石。');const index=s.inventory[s.selectedSlot]===null?s.selectedSlot:s.inventory.findIndex(id=>id===null);if(index<0)throw Error('五格物品栏已满，先右键放下一件物品。');return index;}
function storeItem(s,i){const slot=freeSlot(s);stashHands(s);s.inventory[slot]=i.id;s.selectedSlot=slot;s.held=i.id;const c=swordOf(s,i.id);if(c)c.location='held';}

function releaseItem(s,id,clamped=false){const slot=s.inventory.indexOf(id);if(slot>=0)s.inventory[slot]=null;if(s.held===id){s.held=null;if(clamped&&s.inventory.includes('tongs'))selectSlot(s,s.inventory.indexOf('tongs'));}}

export function orderOre(s,id){empty(s);const o=oreOf(id);if(!o)throw Error('未知矿石。');if(s.items.filter(i=>i.kind==='crate').length+s.orders.length>=MAX_CRATES)throw Error('货位已满，先清空矿筐并在废料箱回收空筐。');const cost=o.cost*PACK_SIZE;if(s.money<cost)throw Error(`资金不足：一筐 ${o.name} 需要 ${cost} 金币。`);s.money-=cost;s.orders.push({id:s.nextId++,ore:id,count:PACK_SIZE,due:s.day+1});return `已订购 ${o.name} ×${PACK_SIZE}，花费 ${cost} 金币。第 ${s.day+1} 天送至庭院货区。`;}
export function nextDay(s){live(s);s.day++;s.dayTime=0;s.furnace.valve=false;const cycleMessage=checkDeadline(s);if(s.gameOver)return cycleMessage;let n=0;for(const order of s.orders.filter(o=>o.due<=s.day)){let p;for(let slot=0;slot<MAX_CRATES;slot++){const candidate=[-9+(slot%6)*1.65,.06,13+Math.floor(slot/6)*1.6];if(!s.items.some(i=>i.kind==='crate'&&Math.hypot(i.position[0]-candidate[0],i.position[2]-candidate[2])<1.15)){p=candidate;break;}}if(!p)continue;s.items.push({id:'crate-'+order.id,kind:'crate',ore:order.ore,count:order.count,stored:false,position:p});order.delivered=true;n++;}s.orders=s.orders.filter(o=>!o.delivered);return `第 ${s.day} 天 · ${n?`${n} 筐矿石已送达庭院，请亲手搬进工房。`:'新的一天开始了。'} ${s.king.status==='fulfilled'?'本期国王订单已完成，等待下期。':'国王订单剩余 '+deadlineText(s)+'。'} ${cycleMessage}`;}
export function selectMold(s,id){empty(s);if(!shapeOf(id))throw Error('未知模具。');if(s.mold.fill>0)throw Error('铁水已流入模具，本次铸型不能再更换。');if(atStation(s,'mold'))throw Error('先用夹钳移走模具内的剑坯。');s.selectedShape=id;return `已装入${shapeOf(id).name}模具，需要 ${shapeOf(id).cost} 块矿石（可混合）。炉内原料和剩余铁水保留。`;}
export function takeOre(s,crateId){live(s);freeSlot(s);const c=s.items.find(i=>i.id===crateId&&i.kind==='crate');if(!c?.stored||!insideWorkshop(c.position))throw Error('这筐矿石还没入库：先把整筐搬入工房并放下。');if(c.count<1)throw Error('矿筐已空。Shift + 左键搬起回收。');if(s.items.filter(i=>i.kind==='ore').length>=24)throw Error('先使用已取出的矿石。');const i={id:'ore-'+s.nextId++,kind:'ore',ore:c.ore,position:[c.position[0],.9,c.position[2]]};s.items.push(i);c.count--;storeItem(s,i);return '已收入物品栏：'+oreOf(i.ore).name+' · 熔点 '+oreOf(i.ore).melt+'°C';}
export function pickup(s,id){live(s);const i=s.items.find(i=>i.id===id),c=swordOf(s,id);if(!i)throw Error('物品不存在。');if(s.inventory.includes(id))return selectSlot(s,s.inventory.indexOf(id));if(i.kind==='crate'){if(atStation(s,'tongs'))throw Error('先放下夹钳中的剑刃。');if(heldItem(s)?.kind==='crate')throw Error('已经抱着矿筐。');stashHands(s);s.held=id;return '抱起整筐矿石。右键放下后恢复之前的物品。';}if(hotSword(c)&&s.held==='tongs'){if(carryingSword(s))throw Error('夹钳已经夹着剑刃。');c.location='tongs';return '夹紧热剑坯。热剑不能收纳，右键放到工位或地面后才能切换物品。';}if(hotSword(c))throw Error('剑坯炽热，请先装备夹钳再左键夹起。');storeItem(s,i);return '已收入物品栏。滚轮或数字 1–5 切换，右键放下当前物品。';}

function removeSword(s,c){const clamped=!!clampedSword(s);s.items=s.items.filter(i=>i.id!==c.id);s.swords=s.swords.filter(x=>x!==c);releaseItem(s,c.id,clamped);}
function rewardSword(s,c,value){s.money+=value;s.tokens++;s.sold++;s.income+=value;s.best=Math.max(s.best,value);removeSword(s,c);}

export function putDown(s,target,position){live(s);const i=heldItem(s);if(!i)return '';const c=carriedSword(s);
 if(c){const item=s.items.find(i=>i.id===c.id),wasClamped=!!clampedSword(s);if(target==='sale'){if(c.stage!=='finished')throw Error('只有完整、冷却后的成剑才能出售。');const value=price(s,c);rewardSword(s,c,value);return `成交！获得 ${value} 金币 + 1 枚炉印。`;}
  
  if(target==='scrap'){if(c.stage!=='broken')throw Error('这把剑尚未断裂，可以继续锻造或冷却出售。');const value=Math.max(3,Math.round(alloyOf(c).cost*shapeOf(c.shape).cost*.2));s.money+=value;removeSword(s,c);return `断剑回收，获得 ${value} 金币。`;}
  if(target?.startsWith('display:')){const slot=Number(target.slice(8));if(!Number.isInteger(slot)||!DISPLAY_SLOTS[slot])throw Error('展示位不存在。');if(c.stage!=='finished')throw Error('墙面挂架只展示已冷却的完整成剑。');if(atStation(s,target))throw Error('这个展示位已有成剑，请先取下。');item.position=[...DISPLAY_SLOTS[slot]];c.location=target;}
  else if(target==='anvil'){if(['finished','broken'].includes(c.stage))throw Error('成剑可出售或展示，断剑请回收。');if(atStation(s,'anvil'))throw Error('铁砧已被占用，先移走上面的剑刃。');item.position=[...POS.anvil];c.location='anvil';}
  else{item.position=dropPosition(position);c.location='floor';}releaseItem(s,c.id,wasClamped);return c.location.startsWith('display:')?'成剑已竖挂上墙。左键可取回物品栏。':target==='anvil'?'剑坯已上砧。放下夹钳，拿起锻锤。':'已放下剑刃。其他工序可以继续进行。';
 }
 if(target==='furnace'&&i.kind==='ore'){const f=s.furnace;if(s.mold.fill||f.valve)throw Error('浇铸期间不能添料，请等待出液结束。');if(f.loaded>=2)throw Error('熔炉最多容纳 2 块矿石。');f.progress=f.progress*f.loaded/(f.loaded+1);f.good=f.good*f.loaded/(f.loaded+1);f.materials=normalizeMaterials([...f.materials,{ore:i.ore,amount:1}]);f.ore=primaryOre(f.materials);f.loaded++;s.items=s.items.filter(x=>x!==i);releaseItem(s,i.id);return `投入${oreOf(i.ore).name} · 炉内 ${f.loaded} 块，配比 ${compositionText(f)}。当前模具用料 ${shapeOf(s.selectedShape).cost} 块。`;}
 if(target==='scrap'&&i.kind==='crate'){if(i.count)throw Error('筐里还有矿石，不能回收。');s.items=s.items.filter(x=>x!==i);s.held=s.inventory[s.selectedSlot];const equipped=swordOf(s,s.held);if(equipped)equipped.location='held';s.money+=2;return '空筐回收，获得 2 金币。';}
 i.position=dropPosition(position);if(i.kind==='crate'){i.position[1]=.06;i.stored=insideWorkshop(i.position);s.held=s.inventory[s.selectedSlot];const equipped=swordOf(s,s.held);if(equipped)equipped.location='held';}else releaseItem(s,i.id);return i.kind==='crate'?(i.stored?'矿筐已入库。左键取矿，Shift + 左键搬动整筐。':'已放下矿筐。仍需搬进工房才能取矿。'):'已放下物品。';}
function dropPosition(p){if(!Array.isArray(p)||p.length!==3||p.some(v=>!Number.isFinite(v)))throw Error('放置位置无效。');return [clamp(p[0],-19,19),clamp(p[1],.06,1.5),clamp(p[2],-13,21)];}
export function temperatureRate(s){const f=s.furnace,offset=f.airflow-50,rate=offset*(offset>=0?1.7:.7);return (rate>0&&f.temp>=2650)||(rate<0&&f.temp<=450)?0:rate;}
export function temperatureTrend(s){const rate=temperatureRate(s);return rate>0?'持续升温 +'+rate.toFixed(1)+'°C/s':rate<0?'持续降温 '+rate.toFixed(1)+'°C/s':s.furnace.airflow===50?'保温 0°C/s':s.furnace.temp>=2650?'已达炉温上限':'已达炉温下限';}
export function adjustAirflow(s,pixels){empty(s);if(!Number.isFinite(pixels))return;s.furnace.airflow=clamp(s.furnace.airflow+pixels*.25,0,100);}

export function toggleValve(s){empty(s);const f=s.furnace;if(f.valve){f.valve=false;return '已关闭出液口，浇铸暂停。';}if(!f.ore||f.progress<100)throw Error('矿石尚未完全熔化。');if(f.loaded<shapeOf(s.mold.shape||s.selectedShape).cost)throw Error('炉内金属不足，补充矿石或换用耗料更少的模具。');if(atStation(s,'mold'))throw Error('先用夹钳移走模具内的剑坯。');if(s.swords.length>=MAX_SWORDS)throw Error('剑刃存放已满，请先出售或回收。');f.valve=true;return '已打开出液口。铁水沿流槽自动流入模具。';}
export const canQuench=s=>{const c=carriedSword(s);return !!c&&!['broken','finished'].includes(c.stage)&&c.hits>=3;};
export function tick(s,dt,action=null){if(s.gameOver)return '';dt=clamp(dt,0,.1);if(!dt)return '';let messages=[];s.dayTime+=dt;if(s.dayTime>=DAY_LENGTH)messages.push(nextDay(s));const failed=checkDeadline(s);if(failed)messages.push(failed);if(s.gameOver)return messages.join(' ');const f=s.furnace,o=alloyOf(f);f.temp=clamp(f.temp+temperatureRate(s)*dt,450,2650);
 if(o&&f.progress<100&&f.temp>=o.melt){f.progress=Math.min(100,f.progress+dt*10);if(f.temp<=o.melt+100)f.good=Math.min(10,f.good+dt);}
 if(f.valve&&f.progress>=100&&o&&!atStation(s,'mold')){if(!s.mold.fill){const shape=shapeOf(s.selectedShape);if(f.loaded<shape.cost){f.valve=false;messages.push('当前模具耗料不足，已关闭出液口。');}else s.mold.shape=shape.id;}if(f.valve){s.mold.fill=Math.min(100,s.mold.fill+dt*26);if(s.mold.fill===100){const smelt=clamp(55+45*f.good/10,35,100),shape=s.mold.shape,c={id:'sword-'+s.nextId++,ore:f.ore,materials:portion(f.materials,shapeOf(shape).cost/f.loaded),additives:[],shape,stage:'blank',location:'mold',hits:0,quality:18+smelt*.17,smelt,quench:0,lastHit:-1};s.swords.push(c);s.items.push({id:c.id,kind:'sword',position:[...POS.mold]});f.materials=portion(f.materials,(f.loaded-shapeOf(shape).cost)/f.loaded).filter(m=>m.amount>0);f.loaded-=shapeOf(shape).cost;f.valve=false;if(!f.loaded)Object.assign(f,{ore:null,materials:[],additives:[],progress:0,good:0});s.mold={fill:0,shape:null};messages.push('铸型完成。用夹钳移走剑坯即可继续浇铸，炉内剩余金属已保留。');}}}
 if(action?.type==='quench'&&canQuench(s)){const c=carriedSword(s);c.quench=Math.min(100,c.quench+dt*25);if(c.quench===100){c.stage='finished';messages.push(`冷却完成。${qualityName(qualityScore(c))}品质，估价 ${price(s,c)} 金币。`);}}
 const royalMessage=checkRoyalProgress(s);if(royalMessage)messages.push(royalMessage);return messages.join(' ');}
export const timingPosition=t=>.5+Math.sin(t*3.2)*.5;
export const timingAccuracy=t=>1-Math.abs(timingPosition(t)-.5)*2;
export function risk(s,c=atStation(s,'anvil')){if(!c||['finished','broken'].includes(c.stage))return 0;const excess=Math.max(0,c.hits+1-5);return clamp(Math.pow(excess,1.45)*.02*(60/(alloyOf(c).tough*shapeOf(c.shape).tough))*(1.25-c.smelt/250),0,.85);}
export function strike(s,accuracy,now,random=Math.random){live(s);const c=atStation(s,'anvil');if(heldItem(s)?.kind!=='hammer')throw Error('先拿起锻锤。');if(!c||['finished','broken'].includes(c.stage))throw Error('铁砧上没有可锻造的剑坯。');if(now-c.lastHit<.42)return null;c.lastHit=now;const chance=risk(s,c),beforeQuality=qualityScore(c);c.hits++;if(chance>0&&random()<chance){c.stage='broken';s.broken++;return {broken:true,chance,message:'剑坯断裂！用夹钳或空手搬到废料箱回收。'};}c.quality+=2.6+clamp(accuracy,0,1)*3.6;c.stage=c.hits>=3?'forged':'blank';const gain=qualityScore(c)-beforeQuality;return {broken:false,gain,message:`${accuracy>.82?'精准落锤':'落锤'} · 品质 +${gain.toFixed(1)} · ${c.hits} 锤`};}
export function attributes(c){if(!c)return null;const o=alloyOf(c),sh=shapeOf(c.shape),q=.58+c.quality*.0062,sm=.8+c.smelt*.002;return {sharp:Math.round(clamp(o.sharp*sh.sharp*q*sm*(1+Math.min(c.hits,30)*.012),1,100)),hard:Math.round(clamp(o.hard*sh.hard*q*sm*(1+Math.min(c.hits,30)*.009)*(c.stage==='finished'?1.1:1),1,100)),tough:Math.round(clamp(o.tough*sh.tough*q*sm*clamp(1+Math.min(c.hits,12)*.006-Math.max(0,c.hits-12)*.012,.65,1.1),1,100)),weight:Number((sh.weight*o.density*(1.04-c.smelt*.0005)*(1-Math.min(c.hits,35)*.003)).toFixed(2))};}
export function qualityScore(c){if(!c||c.stage==='broken')return 0;const a=attributes(c),sh=shapeOf(c.shape);return Number((c.quality*.55+(a.sharp+a.hard+a.tough)/3*.45+clamp(sh.weight/a.weight-.8,0,.6)*8).toFixed(1));}
export function price(s,c=carriedSword(s)||atStation(s,'anvil')||s.swords[0]){if(!c||c.stage==='broken')return 0;const o=alloyOf(c),sh=shapeOf(c.shape),a=attributes(c),score=(a.hard+a.sharp+a.tough)/3;return Math.round(o.value*sh.value*(.5+qualityScore(c)*.014)*(1+score/130)*clamp(sh.weight/a.weight,.8,1.3));}
export const qualityName=q=>q>=100?'传世':q>=82?'大师':q>=65?'卓越':q>=48?'精良':q>=32?'合格':'粗制';
export function objective(s){const c=carriedSword(s)||atStation(s,'anvil')||atStation(s,'mold');if(c?.stage==='broken')return [4,'移走断剑，腾出铁砧','拿到废料箱右键回收，其他工位可继续生产。'];if(c?.stage==='finished')return [6,'出售成剑，或挂墙展示','符合国王订单的成剑自动计入任务，仍可在门内右侧售卖或挂墙展示。'];if(c)return [c.hits>=3?5:4,c.hits>=3?'继续精炼，或收锤冷却':'夹起剑坯，抓准时机锻打',c.location==='mold'?'用夹钳移走剑坯，模具就能铸下一把剑。':'滚轮切换锻锤，在金色中心落锤，至少 3 锤可淬火。热剑坯用夹钳搬运，冷却后才能收入物品栏。'];if(s.furnace.ore){const o=alloyOf(s.furnace);return s.furnace.progress>=100?[3,'铁水就绪，开闸浇铸','放出铁水前仍可换模具。炉内剩余金属将保留。']:[2,'控制炉温，熔化原料',`${compositionText(s.furnace)} · 调节进气量，保持 ${o.melt}–${o.melt+100}°C。`];}if(s.items.some(i=>i.kind==='crate'&&!i.stored))return [1,'把到货矿筐搬进工房','院外货区左键搬整筐，进屋后右键放下。'];if(s.items.some(i=>i.kind==='crate'&&i.stored&&i.count))return [1,'取矿，开始新的一炉','开局赠送一筐赤铁矿。左键取矿、右键投入炉口；不同工位可同时加工。'];return [1,'到院外订矿桌订购原料','院外左侧订矿，王令自动下发。矿石次日到货，睡觉也会推进国王期限。'];}
export function migrateV2(v){if(v?.version!==2)throw Error('旧存档无效');const s=newWorkshop();for(const k of ['money','sold','income','best'])if(Number.isFinite(v[k])&&v[k]>=0)s[k]=v[k];if(v.sword){const c=v.sword,id='sword-'+s.nextId++;s.swords.push({id,ore:'iron',shape:'longsword',stage:c.stage,location:c.location==='mold'?'mold':'anvil',hits:(c.zones||[]).reduce((a,b)=>a+b,0),quality:c.quality,smelt:85,quench:c.quench,lastHit:-1});s.items.push({id,kind:'sword',position:[...(c.location==='mold'?POS.mold:POS.anvil)]});}else if(v.furnace?.ore||v.crucible?.fill||v.mold?.fill){s.furnace={ore:'iron',loaded:1,temp:clamp(v.furnace?.temp||650,450,2650),progress:v.crucible?.fill||v.mold?.fill?100:v.furnace.progress,good:7,valve:false,airflow:10};}return migrateV5({...s,version:5});}
export function migrateV3(v){if(v?.version!==3)throw Error('旧存档无效');const s={...newWorkshop(),...structuredClone(v),version:4,tokens:0,completed:0,swords:[],gameOver:null};s.mold={...v.mold,shape:v.mold.fill?v.selectedShape:null};if(v.sword)s.swords=[{...v.sword,id:'sword'}];delete s.sword;s.king=makeKing(s,1);return migrateV4(s);}
export function migrateV4(v){if(v?.version!==4)throw Error('旧存档无效');const s={...structuredClone(v),version:5,inventory:Array(INVENTORY_SIZE).fill(null),selectedSlot:0};delete s.commissions;delete s.trackedOrder;s.furnace.airflow=clamp((s.furnace.temp-450)/22,0,100);const oldKing=s.king;s.king={...makeKing(s,oldKing.level),ore:oldKing.ore,shape:oldKing.shape,min:oldKing.min,quantity:oldKing.quantity,tokenReward:oldKing.quantity,delivered:oldKing.delivered};if(s.held&&heldItem(s)?.kind!=='crate')s.inventory[0]=s.held;for(const c of s.swords)if(c.location.startsWith('display:'))s.items.find(i=>i.id===c.id).position=[...DISPLAY_SLOTS[Number(c.location.slice(8))]];return migrateV5(s);}

export function migrateV5(v){
 if(v?.version!==5)throw Error('旧存档无效');const s=structuredClone(v);s.version=6;
 // Old settings represented a temperature target; neutral intake preserves the saved temperature.
 s.furnace.materials=s.furnace.ore?[{ore:s.furnace.ore,amount:s.furnace.loaded}]:[];s.furnace.additives=[];s.furnace.airflow=50;
 for(const c of s.swords){c.materials=[{ore:c.ore,amount:shapeOf(c.shape)?.cost}];c.additives=[];if(c.location.startsWith('display:'))s.items.find(i=>i.id===c.id).position=[...DISPLAY_SLOTS[Number(c.location.slice(8))]];}
 return restoreWorkshop(s);
}
function validMaterials(batch,total){
 if(!Array.isArray(batch?.materials)||batch.materials.length>ORES.length||!Array.isArray(batch.additives)||batch.additives.length)return false;
 const m=batch.materials;if(m.some(x=>!x||!oreOf(x.ore)||!Number.isFinite(x.amount)||x.amount<=0||x.amount>2)||new Set(m.map(x=>x.ore)).size!==m.length)return false;
 return Math.abs(m.reduce((n,x)=>n+x.amount,0)-total)<1e-8&&batch.ore===primaryOre(normalizeMaterials(m));
}

export function restoreWorkshop(raw){const s=typeof raw==='string'?JSON.parse(raw):structuredClone(raw),f=(v,a,b)=>Number.isFinite(v)&&v>=a&&v<=b,integer=(v,a,b)=>Number.isInteger(v)&&f(v,a,b),bad=msg=>{throw Error(msg);};if(s?.version!==6||!['money','income','best'].every(k=>f(s[k],0,1e12))||!['sold','broken','completed','tokens','nextId','day'].every(k=>integer(s[k],0,1e9))||s.day<1||s.nextId<1||!f(s.dayTime,0,DAY_LENGTH)||!shapeOf(s.selectedShape))bad('存档无效');if(!s.player||!f(s.player.x,-19.5,19.5)||!f(s.player.z,-13.5,21.5)||!f(s.player.yaw,-1e9,1e9)||!f(s.player.pitch,-1.45,1.45))bad('位置无效');if(!Array.isArray(s.orders)||s.orders.length>MAX_CRATES||s.orders.some(o=>!integer(o.id,1,1e9)||!oreOf(o.ore)||o.count!==PACK_SIZE||!integer(o.due,1,1e9))||new Set(s.orders.map(o=>o.id)).size!==s.orders.length)bad('矿石订单无效');const h=s.furnace;if(!h||!validMaterials(h,h.loaded)||(h.ore!==null&&!oreOf(h.ore))||!f(h.airflow,0,100)||!integer(h.loaded,0,2)||!f(h.temp,450,2650)||!f(h.progress,0,100)||!f(h.good,0,11)||typeof h.valve!=='boolean'||!f(s.mold?.fill,0,100)||(!h.ore&&(h.loaded||h.valve||s.mold.fill))||(h.ore&&h.loaded<1)||(h.valve&&h.progress<100)||(s.mold.fill>0&&(!shapeOf(s.mold.shape)||s.mold.shape!==s.selectedShape||h.loaded<shapeOf(s.mold.shape).cost))||(!s.mold.fill&&s.mold.shape!==null))bad('熔炉无效');if(!Array.isArray(s.items)||s.items.length>MAX_CRATES+26+MAX_SWORDS||s.items.some(i=>!i||typeof i.id!=='string'||!['ore','crate','hammer','tongs','sword'].includes(i.kind)||!Array.isArray(i.position)||i.position.length!==3||!f(i.position[0],-19.5,19.5)||!f(i.position[1],0,3)||!f(i.position[2],-13.5,21.5)||(['ore','crate'].includes(i.kind)&&!oreOf(i.ore))||(i.kind==='crate'&&(!integer(i.count,0,PACK_SIZE)||typeof i.stored!=='boolean'))))bad('物品无效');if(new Set(s.items.map(i=>i.id)).size!==s.items.length||!['hammer','tongs'].every(id=>s.items.filter(i=>i.id===id&&i.kind===id).length===1)||(s.held!==null&&!s.items.some(i=>i.id===s.held)))bad('手持物无效');if(!Array.isArray(s.swords)||s.swords.length>MAX_SWORDS||s.swords.some(c=>typeof c.id!=='string'||!oreOf(c.ore)||!shapeOf(c.shape)||!validMaterials(c,shapeOf(c.shape).cost)||!['blank','forged','finished','broken'].includes(c.stage)||!['mold','anvil','floor','held','tongs','inventory','display:0','display:1','display:2'].includes(c.location)||!integer(c.hits,0,1e6)||!f(c.quality,0,1e8)||!f(c.smelt,0,100)||!f(c.quench,0,100)||!f(c.lastHit,-1,1e12)||(c.location.startsWith('display:')&&c.stage!=='finished')))bad('剑刃无效');if(new Set(s.swords.map(c=>c.id)).size!==s.swords.length||s.items.filter(i=>i.kind==='sword').length!==s.swords.length||s.swords.some(c=>!s.items.some(i=>i.id===c.id&&i.kind==='sword')||(c.location==='held')!==(s.held===c.id)||(c.location==='tongs'&&s.held!=='tongs')))bad('剑刃位置无效');for(const location of ['mold','anvil','held','tongs','display:0','display:1','display:2'])if(s.swords.filter(c=>c.location===location).length>1)bad('工位重复占用');if(atStation(s,'mold')&&s.mold.fill)bad('模具重复占用');s.swords.forEach(c=>c.lastHit=-1);
 if(!Array.isArray(s.inventory)||s.inventory.length!==INVENTORY_SIZE||!integer(s.selectedSlot,0,INVENTORY_SIZE-1))bad('物品栏无效');const ids=s.inventory.filter(id=>id!==null);if(new Set(ids).size!==ids.length||ids.some(id=>!s.items.some(i=>i.id===id&&i.kind!=='crate')))bad('物品栏物品无效');if(heldItem(s)?.kind!=='crate'&&s.held!==s.inventory[s.selectedSlot])bad('装备栏不一致');if(s.swords.some(c=>ids.includes(c.id)!==['inventory','held'].includes(c.location)||(ids.includes(c.id)&&hotSword(c)))||(hotSword(carriedSword(s))&&!ids.includes('tongs')))bad('剑刃收纳状态无效');
 const order=s.king;if(!order||order.id!=='king'||typeof order.title!=='string'||order.title.length>100||!oreOf(order.ore)||!shapeOf(order.shape)||!order.min||Object.entries(order.min).some(([k,v])=>!['sharp','hard','tough','quality'].includes(k)||!f(v,0,200))||!integer(order.quantity,1,1e9)||!integer(order.delivered,0,order.quantity)||!integer(order.level,1,1e9)||!integer(order.tokenReward,1,1e9)||!integer(order.issuedDay,1,1e9)||!['active','fulfilled'].includes(order.status)||(order.status==='fulfilled')!==(order.delivered===order.quantity)||order.deadline!==(order.issuedDay-1+7)*DAY_LENGTH)bad('国王订单无效');if(s.swords.some(c=>c.creditedKing!==undefined&&!integer(c.creditedKing,1,order.level)))bad('王令计数无效');if(s.gameOver!==null&&(!s.gameOver||typeof s.gameOver.reason!=='string'||!integer(s.gameOver.level,1,1e9)))bad('失败状态无效');checkDeadline(s);return s;}
